export const meta = {
  name: 'faucet-full-audit',
  description: 'Full 63-crate bug audit of faucet-stream: parallel per-subsystem finders + adversarial verification',
  phases: [
    { title: 'Find', detail: 'per-subsystem finder agents read real code and report concrete bugs' },
    { title: 'Verify', detail: 'independent adversarial verifier tries to refute each finding' },
  ],
}

const ROOT = '/Users/c-sikawats/Documents/GitHub/Personal/faucet-stream'

const COMMON = `
You are auditing the Rust data-pipeline toolkit "faucet-stream" at ${ROOT}.
PRIMARY GOAL of this project: sources/sinks must be fast, efficient, and RELIABLE. The single worst class of bug is SILENT downstream data corruption / data loss / an exactly-once or resume/bookmark violation. Rank those highest.

Your job: read the ACTUAL code in the files assigned below (use Read/Grep/Bash — do not guess) and find REAL bugs. For each bug you MUST:
- give the exact file path (repo-relative) and line number,
- describe the defect in one sentence,
- give a CONCRETE failure scenario: specific inputs/state -> wrong output / panic / data loss / corruption / leak.

What counts as a bug (report these):
- correctness: wrong results, off-by-one, incorrect pagination/bookmark/offset state, lost records, duplicate records, wrong dedup/last-write-wins, transaction not atomic, commit-token / watermark logic errors, resume skipping or replaying the wrong page.
- data-loss / data-corruption: flush not called before drop, partial writes committed, bookmark advanced before sink confirms, error swallowed then bookmark persisted.
- panics / unwraps on runtime-fallible values, integer overflow, index-out-of-bounds, unwrap on None/Err from external input.
- concurrency: races, deadlocks, lock held across await, cancellation losing buffered data.
- resource leaks: connections/slots/multipart uploads/file handles not released on error paths.
- error handling: failure paths that silently succeed, wrong error variant masking a real failure, retry on non-idempotent op.
- security: SQL/identifier injection, secret leaked into logs/errors/metrics, auth bypass, constant-time comparison missing.

Do NOT report: style, naming, formatting, missing docs, speculative "could be nicer", or anything you cannot tie to a concrete failure. NO false positives — if unsure whether it is real, only include it if you can name the exact triggering condition. Precision over volume.

Return findings via the structured schema. If you find nothing real, return an empty findings array.
`

const FINDINGS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          title: { type: 'string' },
          file: { type: 'string' },
          line: { type: 'integer' },
          category: { type: 'string' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          description: { type: 'string' },
          failure_scenario: { type: 'string' },
          suggested_fix: { type: 'string' },
        },
        required: ['title', 'file', 'line', 'category', 'severity', 'description', 'failure_scenario'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    is_real: { type: 'boolean' },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    corrected_severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
    reasoning: { type: 'string' },
  },
  required: ['is_real', 'confidence', 'reasoning'],
}

const DIMENSIONS = [
  { key: 'core-pipeline', prompt: `Audit the pipeline engine and streaming loop. Files: crates/core/src/pipeline.rs, stage.rs, transforming_source.rs, transform.rs, adaptive.rs, traits.rs, lib.rs. Focus: page loop ordering (masking->quality->contract->drift->write), bookmark persisted ONLY after sink confirms, cooperative cancellation flushing, exactly-once resume/skip/re-anchor logic, DLQ routing vs bookmark advance, apply_stages / explode / PageFn correctness.` },
  { key: 'exactly-once', prompt: `Audit exactly-once delivery. Files: crates/core/src/idempotency.rs, verify.rs, and every sink's idempotent path: crates/sink/{postgres,mysql,mssql,sqlite,bigquery,snowflake,kafka,redis,mongodb,spanner,iceberg}/src (grep write_batch_idempotent, last_committed_token, format_token, parse_token, format_token_with_bookmark, wrap_state). Focus: token monotonicity/parsing, atomicity of records+token commit, resume re-anchor via embedded bookmark, seq fast-forward, page-skip counting, transactional producer fencing.` },
  { key: 'dlq-writemode', prompt: `Audit DLQ + write-modes/upsert. Files: crates/core/src/dlq.rs, write_mode.rs, and write_batch_partial overrides in sinks (grep write_batch_partial, plan_writes, key_to_doc_id, key_to_filter). Focus: plan_writes last-write-wins dedup, missing/null key -> failed routing, delete_marker stripping, envelope shape, on_batch_error policies, partial-failure row indexing.` },
  { key: 'quality-contract', prompt: `Audit quality + contract passes. Files: crates/core/src/quality/*, contract/*. Focus: first-failure-wins ordering, quarantine-requires-DLQ gate, abort writes nothing, per-batch aggregate checks over survivors, compile-time fail-fast validation (regex/enum/bounds), contract fail vs quarantine vs warn semantics, unique/distinct correctness.` },
  { key: 'masking-drift', prompt: `Audit PII masking + schema drift. Files: crates/core/src/masking/*, drift.rs. Focus: masking runs FIRST so PII never leaks (to sink/DLQ/lineage), detector correctness (Luhn, SSN exclusions), deterministic hashing, key never logged, diff_schema top-level classification (additions/widenings/incompatible/droppable), evolve/ignore/quarantine/fail routing, nested-object handling.` },
  { key: 'resilience-retry', prompt: `Audit resilience + retry. Files: crates/core/src/resilience/*, retry.rs. Focus: retry classification, backoff+jitter, circuit breaker consecutive-failure counting and trip, poison-pill action requires DLQ, cancel-aware sleeps, retrying a non-idempotent write, execute_with_policy metering.` },
  { key: 'src-http', prompt: `Audit HTTP-family sources. Files: crates/source/{rest,graphql,xml,grpc}/src. Focus: pagination termination/loop guards (cursor/offset/pagenumber/linkheader/nextlinkinbody), Retry-After/429 handling, JSONPath extraction on empty/null, auth header generation, malformed Link header, bookmark/incremental state, stream_pages emptiness handling.` },
  { key: 'src-sql', prompt: `Audit SQL query sources. Files: crates/source/{postgres,mysql,mssql,sqlite,bigquery,snowflake,spanner}/src. Focus: incremental replication bookmark (@bookmark, max_replication_value, filter_incremental), identifier quoting/SQL injection, type->JSON decoding correctness (nulls, numerics, dates), pagination (pageToken/partition), pool config, shard PK-range bounds.` },
  { key: 'src-cdc', prompt: `Audit CDC sources. Files: crates/source/{postgres-cdc,mysql-cdc,mongodb-cdc}/src. Focus: LSN/binlog/resumeToken durability (confirmed_flush advanced only from durable bookmark), transaction buffering emitted only on commit, max_staged_records OOM guard, slot lifecycle/leak, TLS, resume position capture, partial-transaction leak, offset/pos monotonicity.` },
  { key: 'src-stream-object', prompt: `Audit streaming/object/misc sources. Files: crates/source/{s3,gcs,parquet,kafka,kinesis,redis,mongodb,elasticsearch,websocket,webhook,csv}/src. Focus: kafka offset seek/commit + member rebalance seek, kinesis per-shard sequence bookmark on every page, scroll/scan termination, multi-file schema mismatch, websocket reconnect, webhook server lifecycle, csv streaming, hash-shard predicate, idle/max-messages termination.` },
  { key: 'sink-sql', prompt: `Audit SQL sinks. Files: crates/sink/{postgres,mysql,mssql,sqlite}/src. Focus: multi-row INSERT param limits (2100 for mssql / 65535 pg), transaction wrapping, auto-map column inference correctness, upsert ON CONFLICT/ON DUPLICATE/MERGE key correctness, schema evolution DDL (add/widen/relax), identifier quoting, row-isolation DLQ, NULL handling, batch split boundaries.` },
  { key: 'sink-cloud', prompt: `Audit cloud/analytics sinks. Files: crates/sink/{bigquery,snowflake,iceberg,spanner,kafka,kinesis}/src. Focus: bigquery MERGE/INSERT typed casting + job error detection via error_result, iceberg fast_append + orphan cleanup only on definitive loss, spanner 60k-cell chunking + PK mutations, kafka FuturesUnordered QueueFull retry + transactional side-topic, kinesis PutRecords 500/5MiB/1MiB limits + partial-failure retry, snowflake multi-statement transaction.` },
  { key: 'sink-file-doc', prompt: `Audit file/doc/misc sinks. Files: crates/sink/{parquet,s3,gcs,jsonl,csv,stdout,mongodb,redis,elasticsearch,http}/src. Focus: parquet AsyncArrowWriter flush-before-drop or multipart abort, s3/gcs multipart lifecycle, jsonl/csv buffered writer + compression finalize + parent-dir creation, http concurrency semaphore, elasticsearch bulk NDJSON + partial failure, mongodb insert_many ordered/unordered, redis pipeline.` },
  { key: 'cli-core', prompt: `Audit CLI config/expand/executor. Files: cli/src/{expand.rs,executor.rs,config.rs,merge.rs,compose.rs,interpolate.rs,schema_compose.rs,env_config.rs,env_loader.rs,registry.rs,auth_catalog.rs,state.rs,transforms.rs,scaffold.rs}. Focus: exactly-once dual gate (4 requirements + keyed-upsert alt), write_mode x sink gate, matrix expansion parent/child/depends_on cycle+Kahn, deep-merge semantics, ${...} interpolation cycles + reserved ids (now/backfill), state-key collision detection, semaphore concurrency, on_error stop cooperative cancel.` },
  { key: 'cli-serve', prompt: `Audit the serve control plane. Files: cli/src/serve/** (server,runner,state,idempotency,auth,rbac,audit,history/**,cluster,logs,handlers/**). Focus: bearer auth constant-time + fail-closed unmapped routes, RBAC permission mapping, idempotency atomic claim + fingerprint, instance-fenced orphan recovery + lease TTL, cluster claim_pending/reclaim atomicity + owner fencing, cross-instance cancel, flush-completing cancel grace, SQL history keyset pagination + placeholder dialect, SSE log redaction.` },
  { key: 'cli-runtimes', prompt: `Audit the runtime orchestrators. Files: cli/src/{replication/**,backfill/**,schedule/**,dlq_replay/**,catalog/**,sla/**,notify/**,commands/**,lineage_glue.rs,obs.rs}. Focus: replicate snapshot->CDC handoff (capture position BEFORE snapshot, no gap/dup), backfill window boundaries + tz + state-key namespacing + marker hash, schedule overlap policy + DST + graceful drain, dlq_replay source-override + force at-least-once + fresh DLQ loop-guard, sla staleness/volume math, catalog canonicalize_uri credential redaction, notify coalescing.` },
  { key: 'state-auth-secrets', prompt: `Audit state stores, auth providers, secrets, transforms-sql, lineage. Files: crates/state/{redis,postgres}/src, crates/auth/src, crates/transform-sql/src, crates/lineage/src, cli/src/secrets/**. Focus: FileStateStore atomic rename + key validation, state-key namespacing, OAuth2 single-flight refresh + token rotation + expiry math, secrets redaction boundary (RedactingWriter), duckdb JSON<->Arrow shovel per-page aggregation warning, column-lineage derivation correctness, emission never fails run.` },
]

phase('Find')

const results = await pipeline(
