  (d) => agent(`${COMMON}\n\n=== YOUR ASSIGNMENT: ${d.key} ===\n${d.prompt}`, {
    label: `find:${d.key}`,
    phase: 'Find',
    schema: FINDINGS_SCHEMA,
    agentType: 'general-purpose',
    effort: 'high',
  }),
  (found, d) => {
    const list = (found && found.findings) || []
    if (list.length === 0) return []
    return parallel(list.map((f) => () =>
      agent(
        `You are an adversarial verifier. A finder claims this bug exists in faucet-stream at ${ROOT}. Your job is to REFUTE it. Open the cited file and surrounding code (Read/Grep/Bash), trace the actual control/data flow, and check whether the bug is REAL and reachable.

CLAIM:
- title: ${f.title}
- file: ${f.file}:${f.line}
- category: ${f.category}
- severity: ${f.severity}
- description: ${f.description}
- failure scenario: ${f.failure_scenario}

Decide is_real=true ONLY if you can confirm from the code that the described defect genuinely occurs under the stated (or a real) condition and is not already guarded/handled elsewhere, not a misreading, not intended behavior, and not a test-only path. If the condition can't actually arise, if a caller/validation/default prevents it, if you misread the API, or if you are not confident it is a real defect -> is_real=false. Default to false when uncertain. Give crisp reasoning citing what you saw in the code, and set corrected_severity.`,
        {
          label: `verify:${d.key}:${(f.file || '').split('/').pop()}:${f.line}`,
          phase: 'Verify',
          schema: VERDICT_SCHEMA,
          agentType: 'general-purpose',
          effort: 'high',
        }
      ).then((v) => ({ finding: f, dimension: d.key, verdict: v }))
    ))
  }
)

const all = results.flat().filter(Boolean)
const confirmed = all.filter((r) => r.verdict && r.verdict.is_real)
const rejected = all.filter((r) => r.verdict && !r.verdict.is_real)

log(`Findings raised: ${all.length}. Confirmed: ${confirmed.length}. Rejected by verifier: ${rejected.length}.`)

const sevRank = { critical: 0, high: 1, medium: 2, low: 3 }
confirmed.sort((a, b) => {
  const sa = sevRank[(a.verdict.corrected_severity || a.finding.severity)] ?? 4
  const sb = sevRank[(b.verdict.corrected_severity || b.finding.severity)] ?? 4
  return sa - sb
})

return {
  total_raised: all.length,
  confirmed_count: confirmed.length,
  rejected_count: rejected.length,
  confirmed: confirmed.map((r) => ({
    severity: r.verdict.corrected_severity || r.finding.severity,
    confidence: r.verdict.confidence,
    dimension: r.dimension,
    title: r.finding.title,
    file: r.finding.file,
    line: r.finding.line,
    category: r.finding.category,
    description: r.finding.description,
    failure_scenario: r.finding.failure_scenario,
    suggested_fix: r.finding.suggested_fix,
    verifier_reasoning: r.verdict.reasoning,
  })),
  rejected: rejected.map((r) => ({
    title: r.finding.title,
    file: r.finding.file,
    line: r.finding.line,
    reason_rejected: r.verdict.reasoning,
  })),
}

